using System.IO;
using System.Text.Json;
using VisionFramework;
using VisionPluginContracts;
using VisionPlugins.MapCalibration;
try { int checks=0;void Check(bool ok,string label){if(!ok)throw new Exception(label);checks++;}
var plugin=new MapCalibrationPlugin();var registry=new ModuleRegistry();new ToolPluginRegistry().Register(plugin,registry);Check(registry.Descriptors.Count==1,"Production plugin registration");Check(plugin.Descriptor.Outputs.Single(p=>p.Name=="ModuRunTime").Required,"Original module forces ModuRunTime output");
string directory=Path.GetFullPath("analysis/map-calibration/plugin-replay");Directory.CreateDirectory(directory);
void Matrix(string path,int count=9,bool zero=false)=>File.WriteAllText(Path.Combine(directory,path),"<R><CalibOutputParam><CalibFloatListParam>"+string.Concat(Enumerable.Range(0,count).Select(i=>"<V>"+(!zero&&i is 0 or 4 or 8?"1":"0")+"</V>"))+"</CalibFloatListParam></CalibOutputParam></R>");
Matrix("a.xml");Matrix("b.xml");var values=plugin.Descriptor.Parameters.ToDictionary(p=>p.Name,p=>p.DefaultValue!.Value.Clone());values["InputType"]=JsonSerializer.SerializeToElement(2);values["CalibPath0"]=JsonSerializer.SerializeToElement("a.xml");values["CalibPath1"]=JsonSerializer.SerializeToElement("b.xml");
var module=plugin.CreateRuntime();var native=File.ReadLines("analysis/map-calibration/native/module-runtime-results.jsonl").Select(l=>JsonDocument.Parse(l).RootElement.Clone()).Where(x=>x.TryGetProperty("step",out _));
foreach(var row in native){int step=row.GetProperty("step").GetInt32();if(step==1)Matrix("a.xml",2);if(step==3)Matrix("a.xml");if(step==4)Matrix("a.xml",9,true);if(step==6)Matrix("b.xml",9,true);if(step==7){Matrix("a.xml");Matrix("b.xml");values["CalibPathName"]=JsonSerializer.SerializeToElement("absent/out.xml");values["RefreshFileEnable"]=JsonSerializer.SerializeToElement(true);}
 var run=await module.ExecuteAsync(new("map",directory,new Dictionary<string,PortValue>{{"RefreshSignal",PortValue.Integer(row.GetProperty("refresh").GetInt32())}},values),CancellationToken.None);Check(run.NativeErrorCode==row.GetProperty("code").GetUInt32(),"Original code step "+step);Check(run.Outputs.TryGetValue("ModuRunTime",out var runtime)&&double.IsFinite(runtime.As<double>())&&runtime.As<double>()>=0,"Forced runtime output step "+step);var expected=row.GetProperty("writes").EnumerateArray().ToArray();Check(run.Outputs.Keys.Count(name=>name!="ModuRunTime")==expected.Length,"Only original module writes plus framework timing step "+step);foreach(var item in expected){string name=item.GetProperty("name").GetString()!;Check(run.Outputs[name].As<long>()==item.GetProperty("values")[0].GetInt64(),"Original status "+name+" step "+step);}}
values["InputType"]=JsonSerializer.SerializeToElement(1);values["CalibPathName"]=JsonSerializer.SerializeToElement("");var unsupported=await module.ExecuteAsync(new("map",directory,new Dictionary<string,PortValue>(),values),CancellationToken.None);Check(unsupported.NativeErrorCode==0xe0000314,"Source image mode without either new image rejects early"); values["TeachEnable"]=JsonSerializer.SerializeToElement(true);var teach=await module.ExecuteAsync(new("map",directory,new Dictionary<string,PortValue>(),values),CancellationToken.None);Check(teach.NativeErrorCode==0xe0000314,"Original Teach-enabled missing trigger falls back to absent image input");
values["TeachEnable"]=JsonSerializer.SerializeToElement(false);values["CalibPathName"]=JsonSerializer.SerializeToElement("");values["WeightFun"]=JsonSerializer.SerializeToElement(1);
VisionCore.GrayImage Load(string path){var decoder=System.Windows.Media.Imaging.BitmapDecoder.Create(new Uri(Path.GetFullPath(path)),System.Windows.Media.Imaging.BitmapCreateOptions.PreservePixelFormat,System.Windows.Media.Imaging.BitmapCacheOption.OnLoad);var bitmap=new System.Windows.Media.Imaging.FormatConvertedBitmap(decoder.Frames[0],System.Windows.Media.PixelFormats.Gray8,null,0);var pixels=new byte[bitmap.PixelWidth*bitmap.PixelHeight];bitmap.CopyPixels(pixels,bitmap.PixelWidth,0);return new(bitmap.PixelWidth,bitmap.PixelHeight,pixels);}
var sourceImage=Load("analysis/full-audit/n-image-calibration/solver-fixture/frame-0.bmp");var targetImage=Load("analysis/full-audit/n-image-calibration/solver-fixture/frame-4.bmp");
var first=await module.ExecuteAsync(new("image",directory,new Dictionary<string,PortValue>{{"InputImage1",PortValue.Image(sourceImage)}},values),CancellationToken.None);Check(first.Status==ModuleStatus.Success&&first.Outputs["CalibStatus"].As<long>()==0,"First image waits for its pair");Check(first.Outputs.ContainsKey("ModuRunTime"),"Image wait state emits forced runtime output");
var pair=await module.ExecuteAsync(new("image",directory,new Dictionary<string,PortValue>{{"InputImage2",PortValue.Image(targetImage)}},values),CancellationToken.None);Check(pair.Status==ModuleStatus.Success,"Production shared detector and native-entry image execution");Check(pair.Outputs.ContainsKey("ModuRunTime"),"Image result emits forced runtime output");Check(pair.Outputs["CurCornersPointNum"].As<long>()==168&&pair.Outputs["ObjCornersPointNum"].As<long>()==168,"Original fixture corner count");Check(pair.Outputs["Projection Corners Point"].Elements().Count()==168,"True projected point array");Check(pair.Outputs["ROI"].As<RoiRegionValue>().Regions.Count==0&&pair.Outputs["DetectWidth"].As<IReadOnlyList<double>>().SequenceEqual(new[]{0d,0d}),"Original two zero flat boxes use independent empty Region output");Check(Math.Abs(pair.Outputs["XRatio"].As<double>()-1)<.01&&Math.Abs(pair.Outputs["YRatio"].As<double>()-1)<.01,"Translation fixture ratio invariant");
values["TeachEnable"]=JsonSerializer.SerializeToElement(true);values["CalibPathName"]=JsonSerializer.SerializeToElement("teach-output.xml");var teaching=new Dictionary<string,PortValue>{{"Trigger",PortValue.Text("GO")},{"TeachFlagInput",PortValue.Text("GO")},{"PhysicalPointX",PortValue.Number(10)},{"PhysicalPointY",PortValue.Number(20)},{"WorldRotateAngle",PortValue.Number(30)}};
var taught=await module.ExecuteAsync(new("image",directory,teaching,values),CancellationToken.None);Check(taught.Status==ModuleStatus.Success&&taught.Outputs["MapError"].As<double>()==pair.Outputs["MapError"].As<double>(),"Original matched Teach reuses cached result without images");Check(File.Exists(Path.Combine(directory,"teach-output.xml")),"Actual Teach XML saved");var taughtXml=System.Xml.Linq.XDocument.Load(Path.Combine(directory,"teach-output.xml"));Check(taughtXml.Descendants("TeachWorldPointX").Single().Value=="10"&&!taughtXml.Descendants("SnapWorldCurPointX").Any(),"Original missing snap-world metadata omitted, Teach world retained");
teaching["TeachFlagInput"]=PortValue.Text("NO");var mismatch=await module.ExecuteAsync(new("image",directory,teaching,values),CancellationToken.None);Check(mismatch.NativeErrorCode==0xe0000314,"Original unmatched Teach falls back to fresh image requirement");
Console.WriteLine($"PASS {checks}: production file and image runtime; detector parity remains incomplete");File.WriteAllText("analysis/map-calibration/plugin-checks.json",JsonSerializer.Serialize(new{checks,passed=true,originalSteps=8,imageModeComplete=false}));





} catch(Exception error){Console.Error.WriteLine(error);return 1;} return 0;



